#!/usr/bin/env python3
"""Regenerate changelog cards and navigation.

Run from the docs directory:

    python3 _site/scripts/update_changelogs.py

Cloud release-note frontmatter is the source of truth for the Cloud cards and
navigation. The repository-level CHANGELOG.md is the source of truth for the
current Open source changelog page.
"""

from __future__ import annotations

import json
import re
import sys
from collections import defaultdict
from dataclasses import dataclass
from pathlib import Path


AUTOGENERATED_BLOCK = re.compile(
    r"\{/\*\s*AUTOGENERATED_START\s*\*/\}.*?"
    r"\{/\*\s*AUTOGENERATED_END\s*\*/\}",
    re.DOTALL,
)
FRONTMATTER = re.compile(r"^---\s*\n(.*?)\n---\s*\n", re.DOTALL)
SIDEBAR_TITLE = re.compile(
    r"^sidebarTitle:\s*(?:'([^']+)'|\"([^\"]+)\"|([^#\s]+))\s*$",
    re.MULTILINE,
)
RELEASE_PATH_PREFIX = "resources/changelogs/cloud/release-notes/"
RELEASE_NOTES_OVERVIEW = "resources/changelogs/cloud/release-notes-index"
RELEASE_NOTES_GROUP = "Cloud database release changelog"
CLOUD_CHANGELOG_PATH_PREFIX = "resources/changelogs/cloud"
CLOUD_CHANGELOG_LANDING = "resources/changelogs/cloud/index"
CLOUD_RELEASE_STATUS = "resources/changelogs/cloud/release-status"
CLOUD_DROPDOWN = "Cloud"
CLOUD_CHANGELOG_CARD = re.compile(
    r'(<Card\b(?=[^>]*\btitle="Cloud changelog")[^>]*\bhref=")[^"]+(")',
    re.DOTALL,
)
CLOUD_ARCHIVE_LINK = re.compile(
    r"(\[Browse archived Cloud changelogs\]\()[^)]+(\))"
)
OSS_CHANGELOG_SOURCE = "CHANGELOG.md"
OSS_CHANGELOG_PATH_PREFIX = "resources/changelogs/oss"
OSS_DROPDOWN = "Open source"
SECURITY_CHANGELOG = "resources/changelogs/security-changelog"
OSS_YEAR = re.compile(r"^# (\d{4}) Changelog\s*$", re.MULTILINE)
OSS_RELEASE = re.compile(
    r'^### <a id="(\d+)"></a> ClickHouse release v?(\d+\.\d+)(.*)$'
)
MARKDOWN_HEADING = re.compile(r"^(#{1,6})\s+(.+?)(?:\s+\{#[^}]+\})?$")


@dataclass(frozen=True)
class Release:
    path: str
    version: str
    version_parts: tuple[int, ...]

    @property
    def year(self) -> int:
        return 2000 + self.version_parts[0]


@dataclass(frozen=True)
class AnnualChangelog:
    path: str
    year: int


def read_frontmatter(path: Path, docs_root: Path) -> dict[str, str]:
    content = path.read_text(encoding="utf-8")
    frontmatter = FRONTMATTER.match(content)
    if not frontmatter:
        raise ValueError(f"{path.relative_to(docs_root)}: missing frontmatter")

    fields = {}
    for line in frontmatter.group(1).splitlines():
        key, separator, value = line.partition(":")
        if not separator:
            continue
        value = value.strip()
        if (
            len(value) >= 2
            and value[0] == value[-1]
            and value[0] in {"'", '"'}
        ):
            value = value[1:-1]
        fields[key.strip()] = value
    return fields


def validate_frontmatter(
    path: Path, docs_root: Path, expected: dict[str, str]
) -> None:
    fields = read_frontmatter(path, docs_root)
    mismatches = [
        f"{key} is {fields.get(key)!r}, expected {value!r}"
        for key, value in expected.items()
        if fields.get(key) != value
    ]
    if mismatches:
        raise ValueError(
            f"{path.relative_to(docs_root)}: invalid annual changelog "
            "frontmatter: "
            + "; ".join(mismatches)
        )


def read_release(path: Path, docs_root: Path) -> Release:
    content = path.read_text(encoding="utf-8")
    frontmatter = FRONTMATTER.match(content)
    if not frontmatter:
        raise ValueError(f"{path.relative_to(docs_root)}: missing frontmatter")

    title = SIDEBAR_TITLE.search(frontmatter.group(1))
    if not title:
        raise ValueError(
            f"{path.relative_to(docs_root)}: missing `sidebarTitle` frontmatter"
        )

    version = next(value for value in title.groups() if value is not None)
    try:
        version_parts = tuple(int(part) for part in version.split("."))
    except ValueError as error:
        raise ValueError(
            f"{path.relative_to(docs_root)}: invalid release version {version!r}"
        ) from error
    if len(version_parts) != 2:
        raise ValueError(
            f"{path.relative_to(docs_root)}: expected a major.minor version"
        )

    relative = path.relative_to(docs_root).with_suffix("").as_posix()
    return Release(relative, version, version_parts)


def load_releases(docs_root: Path) -> list[Release]:
    release_dir = docs_root / RELEASE_PATH_PREFIX
    releases = [
        read_release(path, docs_root) for path in sorted(release_dir.glob("*.mdx"))
    ]
    if not releases:
        raise ValueError(f"No Cloud release notes found in {release_dir}")

    versions = [release.version for release in releases]
    duplicates = sorted(
        version for version in set(versions) if versions.count(version) > 1
    )
    if duplicates:
        raise ValueError(
            "Duplicate Cloud release versions: " + ", ".join(duplicates)
        )

    return sorted(releases, key=lambda release: release.version_parts, reverse=True)


def group_releases(releases: list[Release]) -> dict[int, list[Release]]:
    grouped: dict[int, list[Release]] = defaultdict(list)
    for release in releases:
        grouped[release.year].append(release)
    return dict(sorted(grouped.items(), reverse=True))


def load_cloud_changelogs(
    docs_root: Path,
) -> tuple[AnnualChangelog, list[AnnualChangelog]]:
    changelog_dir = docs_root / CLOUD_CHANGELOG_PATH_PREFIX
    current_pages = sorted(
        path for path in changelog_dir.glob("*.mdx") if path.stem.isdigit()
    )
    if len(current_pages) != 1:
        raise ValueError(
            f"Expected exactly one current Cloud changelog in {changelog_dir}, "
            f"found {len(current_pages)}. Move the previous current page into "
            "the archive before adding a new year."
        )

    archive_pages = sorted(
        path
        for path in (changelog_dir / "archive").glob("*.mdx")
        if path.stem.isdigit()
    )
    if not archive_pages:
        raise ValueError("No archived Cloud changelogs found")
    pages = current_pages + archive_pages
    changelogs = [
        AnnualChangelog(
            path.relative_to(docs_root).with_suffix("").as_posix(),
            int(path.stem),
        )
        for path in pages
        if path.stem.isdigit()
    ]
    years = [changelog.year for changelog in changelogs]
    duplicates = sorted(year for year in set(years) if years.count(year) > 1)
    if duplicates:
        raise ValueError(
            "Duplicate Cloud changelog years: "
            + ", ".join(str(year) for year in duplicates)
        )

    current_path = current_pages[0]
    current = AnnualChangelog(
        current_path.relative_to(docs_root).with_suffix("").as_posix(),
        int(current_path.stem),
    )
    validate_frontmatter(
        current_path,
        docs_root,
        {
            "slug": "/whats-new/changelog/cloud",
            "sidebarTitle": str(current.year),
            "title": f"Cloud changelog - {current.year}",
            "description": (
                "ClickHouse Cloud changelog providing descriptions of what "
                "is new in each ClickHouse Cloud release"
            ),
            "doc_type": "changelog",
        },
    )

    archive = sorted(
        (changelog for changelog in changelogs if changelog != current),
        key=lambda changelog: changelog.year,
        reverse=True,
    )
    invalid_archive_years = [
        changelog.year
        for changelog in archive
        if changelog.year >= current.year
    ]
    if invalid_archive_years:
        raise ValueError(
            "Cloud archive years must precede the current year "
            f"{current.year}: "
            + ", ".join(str(year) for year in invalid_archive_years)
        )
    for path in archive_pages:
        year = int(path.stem)
        validate_frontmatter(
            path,
            docs_root,
            {
                "slug": f"/whats-new/cloud/{year}",
                "sidebarTitle": str(year),
                "title": f"Cloud changelog - {year}",
                "description": f"ClickHouse Cloud changelog for {year}",
                "doc_type": "changelog",
            },
        )
    return current, archive


def render_cards(grouped: dict[int, list[Release]]) -> str:
    lines = ["{/* AUTOGENERATED_START */}"]
    for index, (year, releases) in enumerate(grouped.items()):
        if index:
            lines.append("")
        lines.extend(
            [
                f"## {year} {{#{year}}}",
                "",
                '<div className="flex flex-wrap gap-2">',
            ]
        )
        lines.extend(
            f'  <Card title="{release.version}" href="/{release.path}" '
            'className="w-fit" />'
            for release in releases
        )
        lines.append("</div>")
    lines.append("{/* AUTOGENERATED_END */}")
    return "\n".join(lines)


def update_index(docs_root: Path, grouped: dict[int, list[Release]]) -> None:
    index_path = (
        docs_root / "resources/changelogs/cloud/release-notes-index.mdx"
    )
    content = index_path.read_text(encoding="utf-8")
    if not AUTOGENERATED_BLOCK.search(content):
        raise ValueError(
            f"{index_path.relative_to(docs_root)}: missing autogenerated markers"
        )
    updated = AUTOGENERATED_BLOCK.sub(render_cards(grouped), content)
    index_path.write_text(updated, encoding="utf-8")


def update_cloud_landing(
    docs_root: Path,
    current: AnnualChangelog,
    archive: list[AnnualChangelog],
) -> None:
    landing_path = docs_root / f"{CLOUD_CHANGELOG_LANDING}.mdx"
    content = landing_path.read_text(encoding="utf-8")
    updated, card_count = CLOUD_CHANGELOG_CARD.subn(
        lambda match: f'{match.group(1)}/{current.path}{match.group(2)}',
        content,
    )
    updated, archive_count = CLOUD_ARCHIVE_LINK.subn(
        lambda match: f"{match.group(1)}/{archive[0].path}{match.group(2)}",
        updated,
    )
    if card_count != 1 or archive_count != 1:
        raise ValueError(
            f"{landing_path.relative_to(docs_root)}: expected one Cloud "
            f"changelog card and archive link, found {card_count} and "
            f"{archive_count}"
        )
    landing_path.write_text(updated, encoding="utf-8")


def find_navigation_nodes(node, key: str, value: str) -> list[dict]:
    matches = []
    if isinstance(node, dict):
        if node.get(key) == value:
            matches.append(node)
        for child in node.values():
            matches.extend(find_navigation_nodes(child, key, value))
    elif isinstance(node, list):
        for child in node:
            matches.extend(find_navigation_nodes(child, key, value))
    return matches


def update_navigation(
    docs_root: Path,
    grouped: dict[int, list[Release]],
    current_cloud_changelog: AnnualChangelog,
    cloud_archive: list[AnnualChangelog],
    oss_year: int,
) -> None:
    navigation_path = docs_root / "resources/changelogs/navigation.json"
    navigation = json.loads(navigation_path.read_text(encoding="utf-8"))
    cloud_dropdowns = find_navigation_nodes(
        navigation, "dropdown", CLOUD_DROPDOWN
    )
    if len(cloud_dropdowns) != 1:
        raise ValueError(
            f"Expected one {CLOUD_DROPDOWN!r} navigation dropdown, "
            f"found {len(cloud_dropdowns)}"
        )

    cloud_dropdowns[0]["pages"] = [
        CLOUD_CHANGELOG_LANDING,
        current_cloud_changelog.path,
        {
            "group": "Archive",
            "pages": [changelog.path for changelog in cloud_archive],
        },
        CLOUD_RELEASE_STATUS,
        {
            "group": RELEASE_NOTES_GROUP,
            "pages": [RELEASE_NOTES_OVERVIEW]
            + [
                {
                    "group": str(year),
                    "pages": [release.path for release in releases],
                }
                for year, releases in grouped.items()
            ],
        },
    ]

    oss_dropdowns = find_navigation_nodes(navigation, "dropdown", OSS_DROPDOWN)
    if len(oss_dropdowns) != 1:
        raise ValueError(
            f"Expected one {OSS_DROPDOWN!r} navigation dropdown, "
            f"found {len(oss_dropdowns)}"
        )

    archive_years = sorted(
        (
            int(path.stem)
            for path in (docs_root / OSS_CHANGELOG_PATH_PREFIX).glob("*.mdx")
            if path.stem.isdigit() and int(path.stem) != oss_year
        ),
        reverse=True,
    )
    oss_dropdowns[0]["pages"] = [
        f"{OSS_CHANGELOG_PATH_PREFIX}/{oss_year}",
        {
            "group": "Archive",
            "expanded": False,
            "pages": [
                f"{OSS_CHANGELOG_PATH_PREFIX}/{year}" for year in archive_years
            ],
        },
        SECURITY_CHANGELOG,
    ]

    navigation_path.write_text(
        json.dumps(navigation, indent=2, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )


def slugify_anchor(value: str) -> str:
    anchor = re.sub(r"[^a-z0-9]+", "-", value.lower()).strip("-")
    if not anchor:
        raise ValueError(f"Cannot generate an anchor from heading {value!r}")
    return anchor


def load_oss_changelog(
    docs_root: Path,
) -> tuple[int, list[tuple[str, str]], str]:
    source_path = docs_root.parent / OSS_CHANGELOG_SOURCE
    content = source_path.read_text(encoding="utf-8")
    year_matches = list(OSS_YEAR.finditer(content))
    if len(year_matches) != 1:
        raise ValueError(
            f"Expected one current-year heading in {OSS_CHANGELOG_SOURCE}, "
            f"found {len(year_matches)}"
        )

    year_match = year_matches[0]
    year = int(year_match.group(1))
    changelog_dir = docs_root / OSS_CHANGELOG_PATH_PREFIX
    annual_pages = sorted(
        path for path in changelog_dir.glob("*.mdx") if path.stem.isdigit()
    )
    target_path = changelog_dir / f"{year}.mdx"
    if target_path not in annual_pages:
        raise ValueError(
            f"Missing current Open source changelog shell "
            f"{target_path.relative_to(docs_root)}"
        )
    validate_frontmatter(
        target_path,
        docs_root,
        {
            "slug": "/whats-new/changelog/",
            "sidebarTitle": str(year),
            "title": f"Changelog {year}",
            "description": f"Changelog for {year}",
            "doc_type": "changelog",
        },
    )

    archive_pages = [path for path in annual_pages if path != target_path]
    invalid_archive_years = [
        int(path.stem) for path in archive_pages if int(path.stem) >= year
    ]
    if invalid_archive_years:
        raise ValueError(
            "Open source archive years must precede the current year "
            f"{year}: "
            + ", ".join(str(archive_year) for archive_year in invalid_archive_years)
        )
    for path in archive_pages:
        archive_year = int(path.stem)
        validate_frontmatter(
            path,
            docs_root,
            {
                "slug": f"/whats-new/changelog/{archive_year}",
                "sidebarTitle": str(archive_year),
                "title": f"{archive_year} Changelog",
                "description": f"Changelog for {archive_year}",
                "doc_type": "changelog",
            },
        )

    releases = []
    rendered = []
    current_release_anchor = None

    for line in content[year_match.end() :].strip().splitlines():
        release = OSS_RELEASE.match(line)
        if release:
            current_release_anchor, version, suffix = release.groups()
            releases.append((current_release_anchor, version))
            rendered.append(
                f"### ClickHouse release {version}{suffix} "
                f"{{#{current_release_anchor}}}"
            )
            continue

        heading = MARKDOWN_HEADING.match(line)
        if heading:
            level, title = heading.groups()
            if current_release_anchor is None:
                raise ValueError(
                    f"{OSS_CHANGELOG_SOURCE}: heading before first release: "
                    f"{line!r}"
                )
            rendered.append(
                f"{level} {title} "
                f"{{#{current_release_anchor}-{slugify_anchor(title)}}}"
            )
            continue

        rendered.append(line)

    if not releases:
        raise ValueError(f"No Open source releases found in {OSS_CHANGELOG_SOURCE}")
    if len({version for _, version in releases}) != len(releases):
        raise ValueError(
            f"Duplicate Open source release versions in {OSS_CHANGELOG_SOURCE}"
        )

    return year, releases, "\n".join(rendered)


def render_oss_changelog(body: str) -> str:
    lines = [
        "{/* AUTOGENERATED_START */}",
        body,
        "{/* AUTOGENERATED_END */}",
    ]
    return "\n".join(lines)


def update_oss_changelog(docs_root: Path) -> tuple[int, int]:
    year, releases, body = load_oss_changelog(docs_root)
    target_path = docs_root / OSS_CHANGELOG_PATH_PREFIX / f"{year}.mdx"
    content = target_path.read_text(encoding="utf-8")
    frontmatter = FRONTMATTER.match(content)
    if not frontmatter:
        raise ValueError(
            f"{target_path.relative_to(docs_root)}: missing frontmatter"
        )

    generated_comment = (
        "{/* Generated from the repository-level CHANGELOG.md by\n"
        "    _site/scripts/update_changelogs.py. */}"
    )
    updated = (
        frontmatter.group(0).rstrip()
        + "\n\n"
        + generated_comment
        + "\n"
        + render_oss_changelog(body)
        + "\n"
    )
    target_path.write_text(updated, encoding="utf-8")
    return year, len(releases)


def main() -> int:
    docs_root = (
        Path(sys.argv[1]).resolve()
        if len(sys.argv) > 1
        else Path(__file__).resolve().parents[2]
    )
    if not (docs_root / "docs.json").is_file():
        print(f"Error: no docs.json in {docs_root}", file=sys.stderr)
        return 2

    try:
        grouped = group_releases(load_releases(docs_root))
        current_cloud_changelog, cloud_archive = load_cloud_changelogs(
            docs_root
        )
        update_index(docs_root, grouped)
        update_cloud_landing(
            docs_root, current_cloud_changelog, cloud_archive
        )
        oss_year, oss_release_count = update_oss_changelog(docs_root)
        update_navigation(
            docs_root,
            grouped,
            current_cloud_changelog,
            cloud_archive,
            oss_year,
        )
    except (OSError, ValueError, json.JSONDecodeError) as error:
        print(f"Error: {error}", file=sys.stderr)
        return 1

    count = sum(len(releases) for releases in grouped.values())
    print(
        f"Updated {count} Cloud release notes across {len(grouped)} year groups "
        f"and {oss_release_count} Open source {oss_year} releases"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
